package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: each non-blank line is name,grade,terms,contact (terms and contact may be absent or blank), read by
 *  the person form's rules (see PersonValues#from). A name (case ignored) or contact repeated within the paste, or a
 *  paste with no lines, is refused. */
public class ValidateImportPeople {
    public void validate(@RequestBody ImportPeopleRequest request, Out<ImportedPeople> imported) throws InvalidPersonException {
        String text = request == null || request.text() == null ? "" : request.text();
        String by = request == null || request.by() == null ? "" : request.by().trim();
        List<PersonValues> people = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        for (String line : text.split("\\r?\\n")) {
            if (line.isBlank()) {
                continue;
            }
            String[] fields = line.split(",", 4);
            PersonValues values = PersonValues.from(new PersonRequest(fields[0], fields.length > 1 ? fields[1] : "", by, null,
                    "", fields.length > 2 ? fields[2] : "", fields.length > 3 ? fields[3] : ""));
            if (!names.add(PersonRepository.key(values.name()))) {
                throw new InvalidPersonException("The name " + values.name() + " is imported more than once");
            }
            if (values.contact() != null && !contacts.add(values.contact())) {
                throw new InvalidPersonException("The contact " + values.contact() + " is imported more than once");
            }
            people.add(values);
        }
        if (people.isEmpty()) {
            throw new InvalidPersonException("Paste at least one line of name,grade,terms,contact");
        }
        imported.set(new ImportedPeople(people, by));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Checks every imported person before any is added, as the person form checks one (see CheckNewPersonName and
 *  CheckPersonContact): any failing line refuses the whole import. */
public class CheckImportedPeople {
    public void check(@PathVariable("sheetId") String sheetId, @Val ImportedPeople imported, PersonRepository people)
            throws DuplicatePersonNameException, DuplicatePersonContactException {
        String sheet = sheetId.trim();
        for (PersonValues values : imported.people()) {
            if (people.nameTaken(sheet, values.name(), 0) || people.treeTaken(sheet, values.name())) {
                throw new DuplicatePersonNameException(values.name());
            }
            if (values.contact() != null && people.contactTaken(sheet, values.contact(), 0)) {
                throw new DuplicatePersonContactException(values.contact());
            }
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Adds the checked people in the order pasted, each as the person form adds one: stored, written as PERSON_ADDED
 *  (see RecordPersonAdded), then the figures it moved (see Rollup). */
public class AddImportedPeople {
    public void add(@PathVariable("sheetId") String sheetId, @Val ImportedPeople imported, PersonRepository people,
            Rollup rollup, Audit audit, Out<ImportPeopleResult> result)
            throws DuplicatePersonNameException, DuplicatePersonContactException {
        String sheet = sheetId.trim();
        for (PersonValues values : imported.people()) {
            RollupBefore before = rollup.take(sheet);
            Person person = people.add(sheet, values.name(), values.grade(), values.terms(), values.contact());
            new RecordPersonAdded().record(person, values, before, rollup, audit);
        }
        result.set(new ImportPeopleResult(imported.people().size()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with how many imported people were added. */
public class RespondWithImportPeople {
    public void respond(@Val ImportPeopleResult result, ObjectResponse<ImportPeopleResult> response) {
        response.send(result);
    }
}
package net.officefloor.hq.app.person;

/** The outcome of an import of people: how many were added. */
public record ImportPeopleResult(int added) {
}
package net.officefloor.hq.app.person;

import java.util.List;

/** The imported people's values in the order pasted, and who imports them. */
public record ImportedPeople(List<PersonValues> people, String by) {
}
package net.officefloor.hq.app.person;

/** Body of an import of people: lines of name,grade,terms,contact, and who imports them. */
public record ImportPeopleRequest(String text, String by) {
}
# PUT /api/sheets/{sheetId}/people/{personId} — edit a person's name and grade. Invalid values are a
# 400 and a name another person on the sheet has (case and outer spaces ignored), a person left with a
# name or alias used on another sheet of the sheet's tree (one who clashes, until renamed clear), or a
# contact another person has, a 409, neither writing anything; a person not on the sheet is a 404. The body's version is the one the edit was made
# from: when someone has saved the person since, the edit is a 412 and writes nothing. Responds with the person as stored.
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: version
version:
  class: net.officefloor.hq.app.person.CheckPersonVersion
  govern: [ transaction ]
  next: check
check:
  class: net.officefloor.hq.app.person.CheckPersonRename
